css:
/* From Uiverse.io by Admin12121 - Tags: card, popup */
.__UIV_SCOPE__ .wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
}

.__UIV_SCOPE__ article {
  margin-top: 50px;
  width: 90%;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  font-size: 1.125rem;
  padding: 1.5rem;
  background-color: #fff;
  border-radius: 10px;
  box-shadow: 0 15px 20px -10px rgba(0, 0, 0, 0.1);
}

.__UIV_SCOPE__ article > * + * {
  margin-top: 0.5em;
}

.__UIV_SCOPE__ article:is(h1, h2, h3) + * {
  margin-top: 0.5em;
}

.__UIV_SCOPE__ article .h1 {
  font-weight: 900;
  font-size: 2rem;
  line-height: 1.125;
}

.__UIV_SCOPE__ article code {
  background-color: #eee;
  font-weight: 600;
  font-family: monospace;
}

.__UIV_SCOPE__ details {
  position: relative;
  right: 16px;
  margin-top: 35px;
  bottom: 16px;
  color: #6b7280;
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ details div {
  background-color: #1e1e27;
  box-shadow: 0 5px 10px rgba(0, 0, 0, 0.15);
  padding: 1rem;
  border-radius: 8px;
  position: absolute;
  height: 350px;
  width: 400px;
  bottom: calc(100% + 1rem);
  right: -50%;
  overflow: auto;
  transform-origin: 100% 100%;
  color: #95a3b9;
}

.__UIV_SCOPE__ details div::-webkit-scrollbar {
  width: 15px;
  background-color: #1e1e27;
}

.__UIV_SCOPE__ details div::-webkit-scrollbar-thumb {
  width: 5px;
  border-radius: 99em;
  background-color: #95a3b9;
  border: 5px solid #1e1e27;
}

.__UIV_SCOPE__ details div > * + * {
  margin-top: 0.75em;
}

.__UIV_SCOPE__ details div p > code {
  font-size: 1rem;
  font-family: monospace;
}

.__UIV_SCOPE__ details div pre {
  white-space: pre-line;
  border: 1px solid #95a3b9;
  border-radius: 6px;
  font-family: monospace;
  padding: 0.75em;
  font-size: 0.875rem;
  color: #fff;
}

.__UIV_SCOPE__ details[open] div {
  -webkit-animation: scale 0.25s ease;
  animation: scale 0.25s ease;
}

.__UIV_SCOPE__ summary {
  display: inline-flex;
  margin-left: auto;
  margin-right: auto;
  justify-content: center;
  align-items: center;
  font-weight: 600;
  padding: 0.75em 3em 0.75em 1.25em;
  border-radius: 99em;
  color: #fff;
  background-color: #185adb;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
  list-style: none;
  text-align: center;
  cursor: pointer;
  transition: 0.15s ease;
  position: relative;
}

.__UIV_SCOPE__ summary::-webkit-details-marker {
  display: none;
}

.__UIV_SCOPE__ summary:hover, .__UIV_SCOPE__ summary:focus {
  background-color: #1348af;
}

.__UIV_SCOPE__ summary svg {
  position: absolute;
  right: 1.25em;
  top: 50%;
  transform: translateY(-50%);
  width: 1.5em;
  height: 1.5em;
}

@-webkit-keyframes scale {
  0% {
    transform: scale(0);
  }

  100% {
    transform: scale(1);
  }
}

@keyframes scale {
  0% {
    transform: scale(0);
  }

  100% {
    transform: scale(1);
  }
}
